CREATE OR REPLACE FUNCTION public.can_operate(_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _level text;
  _perms jsonb;
BEGIN
  IF _user_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT nivel::text INTO _level FROM public.user_roles WHERE user_id = _user_id LIMIT 1;
  IF _level IS NULL THEN
    RETURN false;
  END IF;

  -- Default system levels that can operate
  IF _level IN ('desenvolvedor', '01', '02', 'gerente', 'motoqueiro', 'membro') THEN
    RETURN true;
  END IF;

  -- Check if permissions are customized in role_permissions table
  SELECT permissions INTO _perms FROM public.role_permissions WHERE level = _level OR nivel = _level LIMIT 1;
  IF _perms IS NOT NULL AND jsonb_typeof(_perms) = 'array' THEN
    IF _perms ? 'create_movement' OR _perms ? 'view_stock' OR _perms ? 'create_sale' THEN
      RETURN true;
    END IF;
  END IF;

  -- Check custom roles table
  IF EXISTS (SELECT 1 FROM public.custom_roles WHERE id = _level) THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_sale(_product_id uuid, _quantity numeric, _unit_price numeric, _buyer_name text, _payment_method text DEFAULT 'dinheiro'::text, _notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _sale_id uuid; _total numeric;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  IF NOT public.can_operate(_uid) THEN RAISE EXCEPTION 'Seu nível não permite registrar vendas'; END IF;
  IF _quantity IS NULL OR _quantity <= 0 THEN RAISE EXCEPTION 'A quantidade deve ser maior que zero'; END IF;
  IF _unit_price IS NULL OR _unit_price < 0 THEN RAISE EXCEPTION 'Valor unitário inválido'; END IF;
  _total := _quantity * _unit_price;
  INSERT INTO public.sales (product_id, seller_id, buyer_name, quantity, unit_price, total_price, payment_method, notes)
  VALUES (_product_id, _uid, COALESCE(NULLIF(trim(_buyer_name),''),'Não informado'), _quantity, _unit_price, _total, _payment_method, _notes)
  RETURNING id INTO _sale_id;
  PERFORM public.register_movement(_product_id, 'saida', _quantity, 'Venda registrada', _sale_id, NULL);
  INSERT INTO public.audit_logs (user_id, action, entity, entity_id, new_data)
  VALUES (_uid, 'create_sale', 'sales', _sale_id, jsonb_build_object('quantity', _quantity, 'total', _total));
  RETURN _sale_id;
END; $function$

CREATE OR REPLACE FUNCTION public.delete_cash_movement(_movement_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _orig record;
  _user_name text := 'Membro';
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  SELECT * INTO _orig
  FROM public.cash_fund_movements
  WHERE id = _movement_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Movimentação de caixa não encontrada';
  END IF;

  SELECT COALESCE(nickname, nome, 'Membro') INTO _user_name
  FROM public.profiles
  WHERE user_id = _uid;

  -- Delete from cash_fund_movements table
  DELETE FROM public.cash_fund_movements
  WHERE id = _movement_id;

  -- Audit log
  INSERT INTO public.audit_logs (user_id, action, entity, entity_id, new_data)
  VALUES (
    _uid,
    'delete_cash_movement',
    'cash_fund_movements',
    _movement_id,
    jsonb_build_object(
      'id', _movement_id,
      'amount', _orig.amount,
      'type', _orig.type,
      'motive', _orig.motive,
      'user_name', _user_name
    )
  );

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_custom_role(_role_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _role public.custom_roles;
  _count_members int;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  SELECT * INTO _role FROM public.custom_roles WHERE id = _role_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cargo não encontrado';
  END IF;

  IF _role.is_system THEN
    RAISE EXCEPTION 'Cargos padrão do sistema não podem ser excluídos';
  END IF;

  -- Check if any member has this role
  SELECT count(*) INTO _count_members FROM public.user_roles WHERE nivel::text = _role_id;
  IF _count_members > 0 THEN
    RAISE EXCEPTION 'Não é possível excluir o cargo pois existem % membros vinculados a ele', _count_members;
  END IF;

  DELETE FROM public.custom_roles WHERE id = _role_id;

  INSERT INTO public.audit_logs (user_id, action, entity, entity_id, old_data)
  VALUES (
    _uid,
    'delete_custom_role',
    'custom_roles',
    _role_id,
    jsonb_build_object('nome', _role.nome)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.heartbeat_user_presence(_status text DEFAULT 'online'::text, _increment_seconds integer DEFAULT 60)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  _current_user_id uuid;
  _existing_status text;
  _existing_since timestamptz;
  _existing_last_seen timestamptz;
BEGIN
  _current_user_id := auth.uid();
  IF _current_user_id IS NULL THEN
    RETURN;
  END IF;

  SELECT status, online_since, last_seen
  INTO _existing_status, _existing_since, _existing_last_seen
  FROM public.user_presence
  WHERE user_id = _current_user_id;

  IF NOT FOUND THEN
    INSERT INTO public.user_presence (
      user_id,
      status,
      last_seen,
      online_since,
      total_seconds_online,
      updated_at
    ) VALUES (
      _current_user_id,
      _status,
      now(),
      now(),
      LEAST(GREATEST(_increment_seconds, 0), 300),
      now()
    );
  ELSE
    -- If user was offline OR last heartbeat was more than 3 minutes ago, reset session start time (online_since)
    IF _existing_status = 'offline' OR _existing_last_seen IS NULL OR _existing_last_seen < (now() - interval '3 minutes') THEN
      _existing_since := now();
    ELSIF _existing_since IS NULL THEN
      _existing_since := now();
    END IF;

    UPDATE public.user_presence
    SET
      status = _status,
      last_seen = now(),
      online_since = _existing_since,
      total_seconds_online = COALESCE(total_seconds_online, 0) + LEAST(GREATEST(_increment_seconds, 0), 300),
      updated_at = now()
    WHERE user_id = _current_user_id;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_audit_action_rpc(_action text, _entity text, _new_data jsonb DEFAULT NULL::jsonb, _old_data jsonb DEFAULT NULL::jsonb, _entity_id text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid;
  _log_id uuid;
  _fallback_uid text;
BEGIN
  _uid := auth.uid();

  IF _uid IS NULL THEN
    _fallback_uid := COALESCE(_new_data->>'user_id', _old_data->>'user_id', _new_data->>'target_id');
    IF _fallback_uid IS NOT NULL AND _fallback_uid ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      _uid := _fallback_uid::uuid;
    END IF;
  END IF;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    entity,
    entity_id,
    old_data,
    new_data,
    created_at
  ) VALUES (
    _uid,
    _action,
    _entity,
    _entity_id,
    _old_data,
    _new_data,
    now()
  )
  RETURNING id INTO _log_id;

  RETURN _log_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.register_cash_movement(_type text, _amount numeric, _motive text, _notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _prev_balance numeric(14,2) := 0;
  _res_balance numeric(14,2) := 0;
  _new_id uuid;
  _user_name text := 'Membro';
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  IF _type NOT IN ('entrada', 'saida') THEN
    RAISE EXCEPTION 'Tipo de movimentação de caixa inválido';
  END IF;

  IF _amount <= 0 THEN
    RAISE EXCEPTION 'O valor da movimentação deve ser maior que zero';
  END IF;

  IF NULLIF(trim(_motive), '') IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo da movimentação de caixa';
  END IF;

  -- Lock latest movement to get exact balance (using scalar expression to guarantee 0 on empty table)
  _prev_balance := COALESCE(
    (SELECT resulting_balance FROM public.cash_fund_movements ORDER BY created_at DESC, id DESC LIMIT 1),
    0
  );

  IF _type = 'entrada' THEN
    _res_balance := _prev_balance + _amount;
  ELSE
    _res_balance := _prev_balance - _amount;
  END IF;

  INSERT INTO public.cash_fund_movements (
    user_id,
    type,
    amount,
    previous_balance,
    resulting_balance,
    motive,
    notes,
    status,
    created_at
  )
  VALUES (
    _uid,
    _type,
    _amount,
    _prev_balance,
    _res_balance,
    trim(_motive),
    NULLIF(trim(_notes), ''),
    'ativo',
    now()
  )
  RETURNING id INTO _new_id;

  -- Resolve actor name for audit log
  SELECT COALESCE(nickname, nome, 'Membro') INTO _user_name
  FROM public.profiles
  WHERE user_id = _uid;

  -- Audit log
  INSERT INTO public.audit_logs (user_id, action, entity, entity_id, new_data)
  VALUES (
    _uid,
    'create_cash_movement',
    'cash_fund_movements',
    _new_id,
    jsonb_build_object(
      'id', _new_id,
      'type', _type,
      'amount', _amount,
      'previous_balance', _prev_balance,
      'resulting_balance', _res_balance,
      'motive', trim(_motive),
      'user_name', _user_name
    )
  );

  RETURN _new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.register_movement(_product_id uuid, _type movement_type, _quantity numeric, _reason text DEFAULT NULL::text, _sale_id uuid DEFAULT NULL::uuid, _reversal_of uuid DEFAULT NULL::uuid, _bau_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    DECLARE 
      _uid uuid := auth.uid(); 
      _prev_chest numeric := 0; 
      _new_chest numeric := 0; 
      _mid uuid; 
      _ativo boolean;
      _target_bau uuid;
      _new_global numeric := 0;
    BEGIN
      IF _uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
      IF NOT public.can_operate(_uid) THEN RAISE EXCEPTION 'Seu nível não permite registrar movimentações'; END IF;
      IF _quantity IS NULL OR _quantity <= 0 THEN RAISE EXCEPTION 'A quantidade deve ser maior que zero'; END IF;

      SELECT ativo INTO _ativo FROM public.products WHERE id = _product_id FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'Produto inválido'; END IF;
      IF _ativo IS NOT TRUE THEN RAISE EXCEPTION 'Produto inativo'; END IF;

      _target_bau := COALESCE(_bau_id, (SELECT id FROM public.baus WHERE ativo = true ORDER BY created_at ASC LIMIT 1));

      -- Ensure row in product_baus exists
      INSERT INTO public.product_baus (product_id, bau_id, quantidade)
      VALUES (_product_id, _target_bau, 0)
      ON CONFLICT (product_id, bau_id) DO NOTHING;

      -- Get current chest balance
      SELECT quantidade INTO _prev_chest FROM public.product_baus 
      WHERE product_id = _product_id AND bau_id = _target_bau FOR UPDATE;
      _prev_chest := COALESCE(_prev_chest, 0);

      IF _type = 'entrada' THEN 
        _new_chest := _prev_chest + _quantity; 
      ELSE 
        _new_chest := _prev_chest - _quantity; 
      END IF;

      IF _new_chest < 0 THEN 
        RAISE EXCEPTION 'Saldo insuficiente no baú: saldo atual % e saída de %', _prev_chest, _quantity; 
      END IF;

      -- Update chest stock in product_baus
      UPDATE public.product_baus 
      SET quantidade = _new_chest, updated_at = now() 
      WHERE product_id = _product_id AND bau_id = _target_bau;

      -- Calculate new global stock across all chests
      SELECT COALESCE(SUM(quantidade), 0) INTO _new_global
      FROM public.product_baus
      WHERE product_id = _product_id;

      -- Update products table with true global sum
      UPDATE public.products 
      SET estoque_atual = _new_global, updated_at = now() 
      WHERE id = _product_id;

      -- Insert stock movement record
      INSERT INTO public.stock_movements (
        product_id, user_id, type, quantity, previous_balance, resulting_balance, reason, sale_id, reversal_of, bau_id
      ) VALUES (
        _product_id, _uid, _type, _quantity, _prev_chest, _new_chest, _reason, _sale_id, _reversal_of, _target_bau
      ) RETURNING id INTO _mid;

      -- Audit log
      INSERT INTO public.audit_logs (user_id, action, entity, entity_id, new_data)
      VALUES (_uid, 'create_movement', 'stock_movements', _mid, jsonb_build_object(
        'type', _type, 
        'quantity', _quantity, 
        'product_id', _product_id, 
        'bau_id', _target_bau,
        'chest_balance', _new_chest,
        'global_balance', _new_global
      ));

      RETURN _mid;
    END; 
    $function$

CREATE OR REPLACE FUNCTION public.reorder_custom_roles(_ordered_ids text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _total int := array_length(_ordered_ids, 1);
  _i int;
  _role_id text;
  _rank_value int;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  IF _total IS NULL OR _total = 0 THEN
    RETURN;
  END IF;

  FOR _i IN 1.._total LOOP
    _role_id := _ordered_ids[_i];
    _rank_value := (_total - _i + 1) * 10;

    UPDATE public.custom_roles
    SET rank = _rank_value, updated_at = now()
    WHERE id = _role_id;
  END LOOP;

  INSERT INTO public.audit_logs (user_id, action, entity, entity_id, new_data)
  VALUES (
    _uid,
    'reorder_custom_roles',
    'custom_roles',
    NULL,
    jsonb_build_object('ordered_ids', _ordered_ids)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_cash_movement(_movement_id uuid, _reason text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _orig record;
  _last_balance numeric(14,2) := 0;
  _new_balance numeric(14,2) := 0;
  _reverse_type text;
  _user_name text := 'Membro';
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  SELECT * INTO _orig
  FROM public.cash_fund_movements
  WHERE id = _movement_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Movimentação de caixa não encontrada';
  END IF;

  IF _orig.status = 'estornado' THEN
    RAISE EXCEPTION 'Esta movimentação já foi estornada';
  END IF;

  _last_balance := COALESCE(
    (SELECT resulting_balance FROM public.cash_fund_movements WHERE status = 'ativo' ORDER BY created_at DESC, id DESC LIMIT 1),
    0
  );

  _reverse_type := CASE WHEN _orig.type = 'entrada' THEN 'saida' ELSE 'entrada' END;

  IF _reverse_type = 'saida' THEN
    _new_balance := _last_balance - _orig.amount;
  ELSE
    _new_balance := _last_balance + _orig.amount;
  END IF;

  -- Mark original movement as estornado
  UPDATE public.cash_fund_movements
  SET status = 'estornado',
      updated_at = now()
  WHERE id = _movement_id;

  SELECT COALESCE(nickname, nome, 'Membro') INTO _user_name
  FROM public.profiles
  WHERE user_id = _uid;

  -- Audit log
  INSERT INTO public.audit_logs (user_id, action, entity, entity_id, new_data)
  VALUES (
    _uid,
    'reverse_cash_movement',
    'cash_fund_movements',
    _movement_id,
    jsonb_build_object(
      'id', _movement_id,
      'amount', _orig.amount,
      'original_type', _orig.type,
      'resulting_balance', _new_balance,
      'reason', NULLIF(trim(_reason), ''),
      'user_name', _user_name
    )
  );

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_movement(_movement_id uuid, _reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    DECLARE 
      _uid uuid := auth.uid(); 
      _m public.stock_movements; 
      _existing uuid;
    BEGIN
      IF NOT public.is_manager(_uid) THEN RAISE EXCEPTION 'Sem permissão para estornar movimentações'; END IF;
      SELECT * INTO _m FROM public.stock_movements WHERE id = _movement_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Movimentação não encontrada'; END IF;
      SELECT id INTO _existing FROM public.stock_movements WHERE reversal_of = _movement_id;
      IF _existing IS NOT NULL THEN RAISE EXCEPTION 'Esta movimentação já foi estornada'; END IF;

      RETURN public.register_movement(
        _m.product_id,
        CASE WHEN _m.type = 'entrada' THEN 'saida'::public.movement_type ELSE 'entrada'::public.movement_type END,
        _m.quantity,
        COALESCE(_reason, 'Estorno de movimentação'),
        NULL,
        _movement_id,
        _m.bau_id
      );
    END; $function$

CREATE OR REPLACE FUNCTION public.reverse_sale(_sale_id uuid, _reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _uid uuid := auth.uid(); _s public.sales;
BEGIN
  IF NOT public.is_manager(_uid) THEN RAISE EXCEPTION 'Sem permissão para estornar vendas'; END IF;
  SELECT * INTO _s FROM public.sales WHERE id = _sale_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Venda não encontrada'; END IF;
  IF _s.status = 'estornada' THEN RAISE EXCEPTION 'Esta venda já foi estornada'; END IF;
  UPDATE public.sales SET status = 'estornada' WHERE id = _sale_id;
  PERFORM public.register_movement(_s.product_id, 'entrada', _s.quantity, COALESCE(_reason,'Estorno de venda'), _sale_id, NULL);
  INSERT INTO public.audit_logs (user_id, action, entity, entity_id, old_data, new_data)
  VALUES (_uid, 'reverse_sale', 'sales', _sale_id, jsonb_build_object('status','concluida'), jsonb_build_object('status','estornada','motivo',_reason));
END; $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_close_poll(p_message_id uuid, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    DECLARE
      v_uid UUID := COALESCE(p_user_id, auth.uid());
      v_poll JSONB;
    BEGIN
      IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autorizado'; END IF;

      SELECT poll_data INTO v_poll
      FROM public.chat_messages
      WHERE id = p_message_id;

      IF v_poll IS NULL THEN RAISE EXCEPTION 'Enquete não encontrada'; END IF;

      v_poll := jsonb_set(v_poll, '{is_closed}', 'true'::jsonb);

      UPDATE public.chat_messages
      SET poll_data = v_poll, updated_at = now()
      WHERE id = p_message_id;

      RETURN v_poll;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.rpc_delete_chat_message(p_message_id uuid, p_for_everyone boolean DEFAULT false, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    DECLARE
      v_uid UUID := COALESCE(p_user_id, auth.uid());
      v_sender_id UUID;
      v_conv_id UUID;
    BEGIN
      IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autorizado'; END IF;

      SELECT sender_id, conversation_id INTO v_sender_id, v_conv_id
      FROM public.chat_messages
      WHERE id = p_message_id;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Mensagem não encontrada';
      END IF;

      IF p_for_everyone THEN
        -- Permitido para o autor ou administradores
        IF v_sender_id = v_uid OR EXISTS (
          SELECT 1 FROM public.chat_participants
          WHERE conversation_id = v_conv_id AND user_id = v_uid AND role = 'admin'
        ) OR EXISTS (
          SELECT 1 FROM public.chat_conversations
          WHERE id = v_conv_id AND created_by = v_uid
        ) THEN
          UPDATE public.chat_messages
          SET is_deleted_for_everyone = true,
              content = '🚫 Mensagem apagada',
              attachment_url = NULL,
              attachment_name = NULL,
              attachment_type = NULL,
              attachment_size = NULL,
              updated_at = now()
          WHERE id = p_message_id;
        ELSE
          RAISE EXCEPTION 'Você não tem permissão para apagar esta mensagem para todos';
        END IF;
      ELSE
        -- Apagar apenas para mim: adiciona o usuário em deleted_for_users
        UPDATE public.chat_messages
        SET deleted_for_users = array_append(COALESCE(deleted_for_users, '{}'::uuid[]), v_uid),
            updated_at = now()
        WHERE id = p_message_id
        AND NOT (v_uid = ANY(COALESCE(deleted_for_users, '{}'::uuid[])));
      END IF;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.rpc_delete_chat_message(p_message_id uuid, p_for_everyone boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    DECLARE
      v_user_id UUID := auth.uid();
      v_msg RECORD;
      v_part RECORD;
      v_now TIMESTAMPTZ := now();
    BEGIN
      IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Não autenticado';
      END IF;

      SELECT * INTO v_msg
      FROM public.chat_messages
      WHERE id = p_message_id;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Mensagem não encontrada';
      END IF;

      IF p_for_everyone THEN
        -- Check if sender or admin of the group
        SELECT role INTO v_part
        FROM public.chat_participants
        WHERE conversation_id = v_msg.conversation_id AND user_id = v_user_id;

        IF v_msg.sender_id != v_user_id AND (v_part.role IS NULL OR v_part.role != 'admin') THEN
          RAISE EXCEPTION 'Apenas o autor ou um administrador pode apagar para todos';
        END IF;

        UPDATE public.chat_messages
        SET
          is_deleted_for_everyone = true,
          content = '🚫 Esta mensagem foi apagada.',
          attachment_url = NULL,
          attachment_name = NULL,
          updated_at = v_now
        WHERE id = p_message_id;

        -- Remove reactions
        DELETE FROM public.chat_message_reactions WHERE message_id = p_message_id;

        RETURN jsonb_build_object('success', true, 'deleted_for_everyone', true);
      ELSE
        -- Delete for me
        UPDATE public.chat_messages
        SET deleted_for_users = array_append(COALESCE(deleted_for_users, '{}'::uuid[]), v_user_id)
        WHERE id = p_message_id;

        RETURN jsonb_build_object('success', true, 'deleted_for_me', true);
      END IF;
    END;
    $function$

