CREATE OR REPLACE FUNCTION public.rpc_manage_group_member(p_conversation_id uuid, p_target_user_id uuid, p_action text, p_new_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    DECLARE
      v_caller_id UUID := auth.uid();
      v_caller_role TEXT;
      v_conv RECORD;
      v_target_profile RECORD;
      v_caller_profile RECORD;
      v_sys_msg TEXT;
      v_now TIMESTAMPTZ := now();
      v_is_admin BOOLEAN := false;
    BEGIN
      IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Não autenticado';
      END IF;

      SELECT * INTO v_conv
      FROM public.chat_conversations
      WHERE id = p_conversation_id AND type = 'group';

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Grupo não encontrado';
      END IF;

      SELECT role INTO v_caller_role
      FROM public.chat_participants
      WHERE conversation_id = p_conversation_id AND user_id = v_caller_id;

      IF v_conv.created_by = v_caller_id OR v_caller_role = 'admin' THEN
        v_is_admin := true;
      END IF;

      IF NOT v_is_admin THEN
        RAISE EXCEPTION 'Apenas administradores do grupo podem gerenciar participantes';
      END IF;

      -- Get target and caller names for system messages
      SELECT COALESCE(nickname, nome, 'Membro') as name INTO v_target_profile
      FROM public.profiles WHERE user_id = p_target_user_id;

      SELECT COALESCE(nickname, nome, 'Administrador') as name INTO v_caller_profile
      FROM public.profiles WHERE user_id = v_caller_id;

      IF p_action = 'add' THEN
        INSERT INTO public.chat_participants (conversation_id, user_id, role, joined_at, last_read_at)
        VALUES (p_conversation_id, p_target_user_id, COALESCE(p_new_role, 'member'), v_now, v_now)
        ON CONFLICT (conversation_id, user_id) DO NOTHING;

        v_sys_msg := '➕ ' || v_caller_profile.name || ' adicionou ' || v_target_profile.name || ' ao grupo.';

      ELSIF p_action = 'remove' THEN
        IF v_conv.created_by = p_target_user_id THEN
          RAISE EXCEPTION 'O criador principal do grupo não pode ser removido';
        END IF;

        DELETE FROM public.chat_participants
        WHERE conversation_id = p_conversation_id AND user_id = p_target_user_id;

        v_sys_msg := '🚪 ' || v_target_profile.name || ' foi removido do grupo por ' || v_caller_profile.name || '.';

      ELSIF p_action = 'make_admin' THEN
        UPDATE public.chat_participants
        SET role = 'admin'
        WHERE conversation_id = p_conversation_id AND user_id = p_target_user_id;

        v_sys_msg := '⭐ ' || v_target_profile.name || ' foi promovido a Administrador por ' || v_caller_profile.name || '.';

      ELSIF p_action = 'remove_admin' THEN
        IF v_conv.created_by = p_target_user_id THEN
          RAISE EXCEPTION 'Não é permitido remover a administração do criador principal';
        END IF;

        UPDATE public.chat_participants
        SET role = 'member'
        WHERE conversation_id = p_conversation_id AND user_id = p_target_user_id;

        v_sys_msg := '👤 ' || v_target_profile.name || ' não é mais Administrador.';

      ELSE
        RAISE EXCEPTION 'Ação inválida: %', p_action;
      END IF;

      -- Post system message
      IF v_sys_msg IS NOT NULL THEN
        INSERT INTO public.chat_messages (
          conversation_id,
          sender_id,
          content,
          message_type,
          status,
          created_at,
          updated_at
        ) VALUES (
          p_conversation_id,
          v_caller_id,
          v_sys_msg,
          'system',
          'delivered',
          v_now,
          v_now
        );

        UPDATE public.chat_conversations
        SET last_message = v_sys_msg, last_message_at = v_now, updated_at = v_now
        WHERE id = p_conversation_id;
      END IF;

      RETURN jsonb_build_object('success', true, 'action', p_action);
    END;
    $function$

CREATE OR REPLACE FUNCTION public.rpc_respond_chat_event(p_message_id uuid, p_response text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    DECLARE
      v_uid UUID := COALESCE(p_user_id, auth.uid());
      v_uid_str TEXT := v_uid::text;
      v_event JSONB;
      v_responses JSONB;
      v_vou JSONB;
      v_nao_vou JSONB;
      v_talvez JSONB;
    BEGIN
      IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autorizado'; END IF;

      SELECT event_data INTO v_event
      FROM public.chat_messages
      WHERE id = p_message_id;

      IF v_event IS NULL THEN RAISE EXCEPTION 'Evento não encontrado'; END IF;
      IF COALESCE((v_event->>'is_cancelled')::boolean, false) THEN
        RAISE EXCEPTION 'Este evento foi cancelado';
      END IF;

      v_responses := COALESCE(v_event->'responses', '{"vou":[],"nao_vou":[],"talvez":[]}'::jsonb);
      v_vou := COALESCE(v_responses->'vou', '[]'::jsonb) - v_uid_str;
      v_nao_vou := COALESCE(v_responses->'nao_vou', '[]'::jsonb) - v_uid_str;
      v_talvez := COALESCE(v_responses->'talvez', '[]'::jsonb) - v_uid_str;

      IF p_response = 'vou' THEN
        v_vou := v_vou || to_jsonb(v_uid_str);
      ELSIF p_response = 'nao_vou' THEN
        v_nao_vou := v_nao_vou || to_jsonb(v_uid_str);
      ELSIF p_response = 'talvez' THEN
        v_talvez := v_talvez || to_jsonb(v_uid_str);
      END IF;

      v_responses := jsonb_build_object('vou', v_vou, 'nao_vou', v_nao_vou, 'talvez', v_talvez);
      v_event := jsonb_set(v_event, '{responses}', v_responses);

      UPDATE public.chat_messages
      SET event_data = v_event, updated_at = now()
      WHERE id = p_message_id;

      RETURN v_event;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.rpc_send_chat_message(p_conversation_id uuid, p_content text, p_message_type text DEFAULT 'text'::text, p_reply_to_id uuid DEFAULT NULL::uuid, p_attachment_url text DEFAULT NULL::text, p_attachment_name text DEFAULT NULL::text, p_attachment_type text DEFAULT NULL::text, p_attachment_size numeric DEFAULT NULL::numeric, p_mentions uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    DECLARE
      v_user_id UUID := auth.uid();
      v_user_role TEXT;
      v_conv RECORD;
      v_new_msg RECORD;
      v_now TIMESTAMPTZ := now();
      v_preview TEXT;
      v_is_admin BOOLEAN := false;
    BEGIN
      IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Não autenticado';
      END IF;

      -- Check conversation exists
      SELECT * INTO v_conv
      FROM public.chat_conversations
      WHERE id = p_conversation_id;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Conversa não encontrada';
      END IF;

      -- Check participant role
      SELECT role INTO v_user_role
      FROM public.chat_participants
      WHERE conversation_id = p_conversation_id AND user_id = v_user_id;

      IF v_user_role IS NULL AND v_conv.created_by != v_user_id THEN
        RAISE EXCEPTION 'Você não é participante desta conversa';
      END IF;

      -- Creator is ALWAYS admin
      IF v_conv.created_by = v_user_id OR v_user_role = 'admin' THEN
        v_is_admin := true;
      END IF;

      -- STRICT BACKEND VALIDATION: only_admins_can_post
      IF v_conv.type = 'group' AND v_conv.only_admins_can_post = true AND NOT v_is_admin THEN
        RAISE EXCEPTION 'Somente administradores podem enviar mensagens neste grupo';
      END IF;

      -- Preview calculation for last_message
      IF p_message_type = 'image' THEN
        v_preview := '📷 Imagem';
      ELSIF p_message_type = 'video' THEN
        v_preview := '🎥 Vídeo';
      ELSIF p_message_type = 'audio' THEN
        v_preview := '🎙️ Mensagem de áudio';
      ELSIF p_message_type = 'document' THEN
        v_preview := COALESCE('📄 ' || p_attachment_name, '📄 Documento');
      ELSE
        v_preview := TRIM(p_content);
      END IF;

      -- Insert message
      INSERT INTO public.chat_messages (
        conversation_id,
        sender_id,
        content,
        status,
        message_type,
        reply_to_id,
        attachment_url,
        attachment_name,
        attachment_type,
        attachment_size,
        mentions,
        created_at,
        updated_at
      ) VALUES (
        p_conversation_id,
        v_user_id,
        TRIM(p_content),
        'sent',
        COALESCE(p_message_type, 'text'),
        p_reply_to_id,
        p_attachment_url,
        p_attachment_name,
        p_attachment_type,
        p_attachment_size,
        COALESCE(p_mentions, '{}'::uuid[]),
        v_now,
        v_now
      )
      RETURNING * INTO v_new_msg;

      -- Update conversation
      UPDATE public.chat_conversations
      SET
        last_message = v_preview,
        last_message_at = v_now,
        last_message_sender_id = v_user_id,
        updated_at = v_now
      WHERE id = p_conversation_id;

      -- Update sender's last_read_at
      UPDATE public.chat_participants
      SET last_read_at = v_now
      WHERE conversation_id = p_conversation_id AND user_id = v_user_id;

      RETURN to_jsonb(v_new_msg);
    END;
    $function$

CREATE OR REPLACE FUNCTION public.rpc_set_conversation_mute(p_conversation_id uuid, p_duration_minutes integer, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    DECLARE
      v_uid UUID := COALESCE(p_user_id, auth.uid());
      v_until TIMESTAMPTZ;
    BEGIN
      IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autorizado'; END IF;

      IF p_duration_minutes = 0 THEN
        -- Desativa silenciamento
        UPDATE public.chat_participants
        SET is_muted = false, muted_until = NULL
        WHERE conversation_id = p_conversation_id AND user_id = v_uid;
      ELSIF p_duration_minutes = -1 THEN
        -- Silencia indefinidamente
        UPDATE public.chat_participants
        SET is_muted = true, muted_until = NULL
        WHERE conversation_id = p_conversation_id AND user_id = v_uid;
      ELSE
        -- Silencia por duração específica
        v_until := now() + (p_duration_minutes || ' minutes')::interval;
        UPDATE public.chat_participants
        SET is_muted = true, muted_until = v_until
        WHERE conversation_id = p_conversation_id AND user_id = v_uid;
      END IF;
    END;
    $function$

