CREATE OR REPLACE FUNCTION public.rpc_update_group_settings(p_conversation_id uuid, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_only_admins_can_post boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    DECLARE
      v_caller_id UUID := auth.uid();
      v_caller_role TEXT;
      v_conv RECORD;
      v_caller_name TEXT;
      v_sys_msg TEXT;
      v_now TIMESTAMPTZ := now();
      v_is_admin BOOLEAN := false;
    BEGIN
      IF v_caller_id IS NULL THEN
        RAISE EXCEPTION 'Não autenticado';
      END IF;

      SELECT * INTO v_conv
      FROM public.chat_conversations
      WHERE id = p_conversation_id AND type = 'group';

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Grupo não encontrado';
      END IF;

      SELECT role INTO v_caller_role
      FROM public.chat_participants
      WHERE conversation_id = p_conversation_id AND user_id = v_caller_id;

      -- Check admin authorization: Creator, Chat Admin, Developer, or Management
      IF v_conv.created_by = v_caller_id 
         OR v_caller_role = 'admin' 
         OR EXISTS (SELECT 1 FROM public.profiles WHERE user_id = v_caller_id AND is_developer = true)
         OR EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = v_caller_id AND nivel::text IN ('desenvolvedor', '01', '02', 'gerente'))
      THEN
        v_is_admin := true;
      END IF;

      IF NOT v_is_admin THEN
        RAISE EXCEPTION 'Apenas administradores podem alterar as configurações do grupo';
      END IF;

      SELECT COALESCE(nickname, nome, 'Administrador') INTO v_caller_name
      FROM public.profiles WHERE user_id = v_caller_id;

      -- Check if only_admins_can_post changed
      IF p_only_admins_can_post IS NOT NULL AND p_only_admins_can_post != v_conv.only_admins_can_post THEN
        IF p_only_admins_can_post = true THEN
          v_sys_msg := '🔒 ' || v_caller_name || ' definiu que somente administradores podem enviar mensagens neste grupo.';
        ELSE
          v_sys_msg := '🔓 ' || v_caller_name || ' liberou o envio de mensagens para todos os participantes.';
        END IF;
      ELSIF p_title IS NOT NULL AND TRIM(p_title) != '' AND TRIM(p_title) != v_conv.title THEN
        v_sys_msg := '✏️ ' || v_caller_name || ' alterou o nome do grupo para: "' || TRIM(p_title) || '".';
      ELSIF p_avatar_url IS NOT NULL AND p_avatar_url != COALESCE(v_conv.avatar_url, '') THEN
        v_sys_msg := '🖼️ ' || v_caller_name || ' alterou a foto do grupo.';
      END IF;

      UPDATE public.chat_conversations
      SET
        title = COALESCE(NULLIF(TRIM(p_title), ''), title),
        description = COALESCE(p_description, description),
        avatar_url = COALESCE(p_avatar_url, avatar_url),
        only_admins_can_post = COALESCE(p_only_admins_can_post, only_admins_can_post),
        updated_at = v_now
      WHERE id = p_conversation_id;

      -- Post system message if relevant
      IF v_sys_msg IS NOT NULL THEN
        INSERT INTO public.chat_messages (
          conversation_id,
          sender_id,
          content,
          message_type,
          status,
          created_at,
          updated_at
        ) VALUES (
          p_conversation_id,
          v_caller_id,
          v_sys_msg,
          'system',
          'delivered',
          v_now,
          v_now
        );

        UPDATE public.chat_conversations
        SET last_message = v_sys_msg, last_message_at = v_now, updated_at = v_now
        WHERE id = p_conversation_id;
      END IF;

      RETURN jsonb_build_object(
        'success', true, 
        'only_admins_can_post', COALESCE(p_only_admins_can_post, v_conv.only_admins_can_post)
      );
    END;
    $function$

CREATE OR REPLACE FUNCTION public.rpc_vote_poll(p_message_id uuid, p_option_id text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    DECLARE
      v_uid UUID := COALESCE(p_user_id, auth.uid());
      v_uid_str TEXT := v_uid::text;
      v_poll JSONB;
      v_options JSONB;
      v_new_options JSONB := '[]'::jsonb;
      v_is_multi BOOLEAN;
      v_is_closed BOOLEAN;
      v_expires_at TIMESTAMPTZ;
      v_opt JSONB;
      v_votes JSONB;
      v_has_voted BOOLEAN;
      v_now TIMESTAMPTZ := now();
    BEGIN
      IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autorizado'; END IF;

      SELECT poll_data INTO v_poll
      FROM public.chat_messages
      WHERE id = p_message_id;

      IF v_poll IS NULL THEN RAISE EXCEPTION 'Enquete não encontrada'; END IF;

      v_is_closed := COALESCE((v_poll->>'is_closed')::boolean, false);
      v_expires_at := (v_poll->>'expires_at')::timestamptz;

      IF v_is_closed OR (v_expires_at IS NOT NULL AND v_now > v_expires_at) THEN
        RAISE EXCEPTION 'Esta enquete já está encerrada';
      END IF;

      v_is_multi := COALESCE((v_poll->>'is_multiple_choice')::boolean, false);
      v_options := v_poll->'options';

      -- Atualiza votos
      FOR v_opt IN SELECT * FROM jsonb_array_elements(v_options)
      LOOP
        v_votes := COALESCE(v_opt->'votes', '[]'::jsonb);
        v_has_voted := v_votes @> to_jsonb(v_uid_str);

        IF (v_opt->>'id') = p_option_id THEN
          -- Se clicou na opção atual: alterna o voto
          IF v_has_voted THEN
            v_votes := v_votes - v_uid_str;
          ELSE
            v_votes := v_votes || to_jsonb(v_uid_str);
          END IF;
        ELSE
          -- Se for escolha única, remove o voto das outras opções
          IF NOT v_is_multi AND v_has_voted THEN
            v_votes := v_votes - v_uid_str;
          END IF;
        END IF;

        v_new_options := v_new_options || jsonb_build_array(
          jsonb_set(v_opt, '{votes}', v_votes)
        );
      END LOOP;

      v_poll := jsonb_set(v_poll, '{options}', v_new_options);

      UPDATE public.chat_messages
      SET poll_data = v_poll, updated_at = now()
      WHERE id = p_message_id;

      RETURN v_poll;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.set_member_level(_target_user uuid, _nivel app_level)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
    DECLARE _uid uuid := auth.uid(); _old public.app_level;
    BEGIN
      IF _uid IS NOT NULL AND NOT public.is_admin(_uid) THEN
        RAISE EXCEPTION 'Sem permissão para alterar níveis';
      END IF;

      SELECT nivel INTO _old FROM public.user_roles WHERE user_id = _target_user;

      INSERT INTO public.user_roles (user_id, nivel, updated_at)
      VALUES (_target_user, _nivel, now())
      ON CONFLICT (user_id) DO UPDATE SET nivel = EXCLUDED.nivel, updated_at = now();

      IF _uid IS NOT NULL THEN
        INSERT INTO public.audit_logs (user_id, action, entity, entity_id, old_data, new_data)
        VALUES (_uid, 'update_level', 'user_roles', _target_user, jsonb_build_object('nivel', _old), jsonb_build_object('nivel', _nivel));
      END IF;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.sync_discord_user_rpc(_discord_id text, _discord_username text, _discord_avatar_url text, _discord_email text, _discord_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
      DECLARE
        _new_uid uuid := auth.uid();
        _existing_uid uuid;
        _needs_merge boolean := false;
        _count int;
      BEGIN
        IF _new_uid IS NULL THEN
          RAISE EXCEPTION 'Não autenticado';
        END IF;

        -- 1. Check if profile already exists for this discord_id
        SELECT user_id INTO _existing_uid FROM public.profiles WHERE discord_id = _discord_id LIMIT 1;

        IF _existing_uid IS NOT NULL THEN
          IF _existing_uid != _new_uid THEN
            _needs_merge := true;
          END IF;
        ELSE
          -- 2. Not found by discord_id. Try by email
          SELECT id INTO _existing_uid FROM auth.users WHERE email = _discord_email AND id != _new_uid LIMIT 1;
          IF _existing_uid IS NOT NULL AND EXISTS (SELECT 1 FROM public.profiles WHERE user_id = _existing_uid) THEN
            _needs_merge := true;
          ELSE
            -- 3. Try by nickname or name
            SELECT user_id INTO _existing_uid FROM public.profiles 
            WHERE (LOWER(nickname) = LOWER(_discord_username) OR LOWER(nome) = LOWER(_discord_name))
              AND user_id != _new_uid
            LIMIT 1;
            IF _existing_uid IS NOT NULL THEN
              _needs_merge := true;
            END IF;
          END IF;
        END IF;

        IF _needs_merge THEN
          -- Merge old user -> new user
          DELETE FROM public.profiles WHERE user_id = _new_uid;
          DELETE FROM public.user_roles WHERE user_id = _new_uid;

          UPDATE public.profiles SET 
            user_id = _new_uid,
            discord_id = _discord_id,
            discord_username = _discord_username,
            discord_avatar_url = _discord_avatar_url,
            discord_email = _discord_email,
            nome = COALESCE(NULLIF(nome, ''), _discord_name),
            avatar_url = COALESCE(avatar_url, _discord_avatar_url),
            updated_at = now()
          WHERE user_id = _existing_uid;

          UPDATE public.user_roles SET 
            user_id = _new_uid,
            updated_at = now()
          WHERE user_id = _existing_uid;

          UPDATE public.signup_requests SET 
            user_id = _new_uid,
            updated_at = now()
          WHERE user_id = _existing_uid;

          UPDATE public.stock_movements SET 
            user_id = _new_uid
          WHERE user_id = _existing_uid;

          UPDATE public.sales SET 
            seller_id = _new_uid
          WHERE seller_id = _existing_uid;

          UPDATE public.goals SET 
            user_id = _new_uid
          WHERE user_id = _existing_uid;

          UPDATE public.audit_logs SET 
            user_id = _new_uid
          WHERE user_id = _existing_uid;

          UPDATE public.signup_requests SET
            reviewed_by = _new_uid
          WHERE reviewed_by = _existing_uid;
        ELSE
          -- No merge needed. Upsert profile and role
          IF EXISTS (SELECT 1 FROM public.profiles WHERE user_id = _new_uid) THEN
            UPDATE public.profiles SET
              discord_id = _discord_id,
              discord_username = _discord_username,
              discord_avatar_url = _discord_avatar_url,
              discord_email = _discord_email,
              nome = COALESCE(NULLIF(nome, ''), _discord_name),
              avatar_url = COALESCE(avatar_url, _discord_avatar_url),
              updated_at = now()
            WHERE user_id = _new_uid;
          ELSE
            INSERT INTO public.profiles (
              user_id, nome, nickname, avatar_url, status, 
              discord_id, discord_username, discord_avatar_url, discord_email
            )
            VALUES (
              _new_uid, _discord_name, _discord_username, _discord_avatar_url, 'ativo',
              _discord_id, _discord_username, _discord_avatar_url, _discord_email
            );
          END IF;

          IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _new_uid) THEN
            SELECT count(*) INTO _count FROM public.user_roles;
            INSERT INTO public.user_roles (user_id, nivel)
            VALUES (_new_uid, CASE WHEN _count = 0 OR _discord_id = '917826984778797087' THEN '01'::public.app_level ELSE 'novato'::public.app_level END);
          END IF;
        END IF;

        -- Regra especial: ID do Discord 917826984778797087 é sempre cargo 01
        IF _discord_id = '917826984778797087' THEN
          INSERT INTO public.user_roles (user_id, nivel)
          VALUES (_new_uid, '01'::public.app_level)
          ON CONFLICT (user_id) DO UPDATE SET nivel = '01'::public.app_level, updated_at = now();
        END IF;
      END;
      $function$

CREATE OR REPLACE FUNCTION public.verify_player_password(_user_id uuid, _senha text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _encrypted text;
BEGIN
  IF _user_id IS NULL OR _senha IS NULL OR length(trim(_senha)) = 0 THEN
    RETURN false;
  END IF;

  SELECT u.encrypted_password
    INTO _encrypted
  FROM auth.users u
  JOIN public.profiles p ON p.user_id = u.id
  WHERE u.id = _user_id
    AND p.status = 'ativo'
    AND u.deleted_at IS NULL;

  IF _encrypted IS NULL THEN
    RETURN false;
  END IF;

  RETURN _encrypted = extensions.crypt('twtools:' || trim(_senha) || ':v1!', _encrypted);
END;
$function$
